-- 1114: sfec.html - redesign as UTAP-style lead-magnet page.
-- Benefit-led hero + Quick Facts card (claim type = reimbursement, quarterly
-- PayNow Corporate/GIRO payout), worked claim examples, 30 Nov 2026 deadline
-- band + fresh-tranche note (redesigned SFEC from 1 Dec 2026 under EWTP),
-- eligibility cards, 5-step claim walkthrough, and the SFEC Claim Kit lead
-- form (mmd/sfec_lead_form.phtml -> contacts pipeline -> enquiry@).
-- Facts sourced from skillsfuture.gobusiness.gov.sg + EnterpriseSG FAQ, Aug 2026.
-- SG-only content: guarded on the SG base_url so partner instances (MY/GH) no-op.
-- Content is the full page blob, hex-encoded (ASCII-only) to survive apply.php's
-- utf8 DSN and its semicolon statement splitter. Idempotent: same UPDATE, same result.
UPDATE cms_page
   SET title = 'SkillsFuture Enterprise Credit (SFEC) - S$10,000 Training Credit with 90% Reimbursement for Companies',
       meta_description = 'SFEC gives eligible Singapore employers a S$10,000 credit that reimburses 90% of out-of-pocket training fees, paid out quarterly via PayNow Corporate or GIRO. Unused credit expires 30 Nov 2026. Check eligibility and claim steps here.',
       content = CONVERT(UNHEX('') USING utf8)
 WHERE identifier = 'sfec.html'
   AND EXISTS (SELECT 1 FROM core_config_data
                WHERE path = 'web/unsecure/base_url'
                  AND value LIKE '%tertiarycourses.com.sg%');
